const ai=$('Parse AI').first().json||{}; const s=$('Get Active Session').first().json||{}; const input=$('Edit Fields').first().json;
let services=[]; let doctors=[];
try{services=$('Get Services').all().map(i=>i.json)}catch(e){}
try{doctors=$('Get Doctors For Service').all().map(i=>i.json)}catch(e){}
const type=String(ai.type||'UNKNOWN').toUpperCase(); const value=String(ai.value||'').trim();
let serviceId=s.serviceId??null, doctorId=s.doctorId??null, date=s.appointmentDate??null, state=s.state, reply='', action='NONE';

if(s.state==='STARTED'||s.state==='COLLECTING_SERVICE'){
 const m=value.toLowerCase();
 const match=services.find(x=>String(x.name).toLowerCase()===m);
 if(type==='SERVICE'&&match){serviceId=match.id; doctorId=null; date=null; state='COLLECTING_DOCTOR'; reply=`Great! You selected ${match.name}. Please choose a doctor.`;}
 else {state='COLLECTING_SERVICE'; reply=`Please choose a service:\n\n${services.map((x,i)=>`${i+1}. ${x.name}`).join('\n')}`;}
} else if(s.state==='COLLECTING_DOCTOR'){
 const m=value.toLowerCase().replace(/^dr\.?\s+/,'');
 const match=doctors.find(x=>String(x.name).toLowerCase().replace(/^dr\.?\s+/,'')===m);
 if(type==='DOCTOR'&&match){doctorId=match.id; date=null; state='COLLECTING_DATE'; reply=`Great! You've selected ${match.name}. What date would you like?`;}
 else {state='COLLECTING_DOCTOR'; reply=`Please choose a doctor:\n\n${doctors.map((x,i)=>`${i+1}. ${x.name}`).join('\n')}`;}
} else if(s.state==='COLLECTING_DATE'){
 if(type==='DATE'&&/^\d{4}-\d{2}-\d{2}$/.test(value)){date=value; state='SHOWING_SLOTS'; action='CHECK_AVAILABILITY'; reply=`Thank you. Let me check available slots for ${date}.`;}
 else {state='COLLECTING_DATE'; reply='Please provide the appointment date, for example 26-08-2026.';}
}
return [{json:{serviceId,doctorId,appointmentDate:date,state,action,reply_to_patient:reply}}];

const a=$json||{}; const slots=Array.isArray(a.slots)?a.slots:[]; const date=a.date||$('Process AI Selection').first().json.appointmentDate;
const fmt=v=>{const [h,m]=String(v).split(':').map(Number);return `${h%12||12}:${String(m||0).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
return [{json:{slots,date,reply_to_patient:slots.length?`Available slots for ${date}:

