const doctor = $('Get Doctors After Service').first().json;
const serviceId = $('Process AI Selection').first().json.serviceId;
const reply = `Great! You'll be seeing ${doctor.name}${doctor.specialization ? ` (${doctor.specialization})` : ''}. What date would you like?`;
return [{ json: { serviceId, doctorId: doctor.id, appointmentDate: null, state: 'COLLECTING_DATE', reply_to_patient: reply } }];
